<template>
	<section class="planner-strategies" :class="{ 'planner-strategies--compact': compact }">
		<div v-if="successful.length" class="planner-strategies__grid">
			<article v-for="result in successful" :key="result.strategy" class="planner-strategy-card" :class="{ 'planner-strategy-card--selected': result.strategy === selected }" role="button" tabindex="0" @click="choose(result.strategy)" @keydown.enter.prevent="choose(result.strategy)">
				<header><div class="strategy-mark"><i class="pi pi-chart-line"></i></div><div><h3>{{ label(result.strategy) }}</h3><span>{{ result.strategy_description || "Optimization strategy" }}</span></div><Tag v-if="result.strategy === selected" value="Selected" severity="success" rounded /></header>
				<div class="strategy-metrics"><div><span>Lays</span><strong>{{ result.summary.total_lays }}</strong></div><div><span>Markers</span><strong>{{ result.summary.unique_markers }}</strong></div><div><span>Overcut</span><strong>{{ number(result.summary.overcut_pct) }}%</strong></div><div><span>Undercut</span><strong>{{ number(result.summary.undercut_pct) }}%</strong></div></div>
				<Button v-if="!compact" :label="result.strategy === selected ? 'Selected Plan' : 'Select Strategy'" :icon="result.strategy === selected ? 'pi pi-check' : 'pi pi-arrow-right'" size="small" :severity="result.strategy === selected ? 'success' : 'secondary'" :outlined="result.strategy !== selected" :loading="selecting === result.strategy" :disabled="!canSelect || Boolean(selecting) || result.strategy === selected" @click.stop="choose(result.strategy)" />
				<i v-else :class="result.strategy === selected ? 'pi pi-check-circle strategy-state strategy-state--selected' : selecting === result.strategy ? 'pi pi-spin pi-spinner strategy-state' : 'pi pi-chevron-right strategy-state'" aria-hidden="true" />
			</article>
		</div>
		<div v-if="failed.length" class="planner-outcomes">
			<header><span>Other outcomes</span><strong>{{ failed.length }}</strong></header>
			<div class="planner-outcomes__list"><article v-for="result in failed" :key="result.strategy" class="planner-strategy-card planner-strategy-card--failed"><div class="strategy-mark"><i :class="result.deduplicated ? 'pi pi-clone' : result.dominated ? 'pi pi-arrow-down' : 'pi pi-times'"></i></div><div><h3>{{ label(result.strategy) }}</h3><span>{{ outcome(result) }}</span></div></article></div>
		</div>
		<div v-if="!successful.length && !failed.length" class="strategy-empty"><i class="pi pi-chart-bar"></i><strong>No strategy results yet</strong><span>Run Optimize to compare the available planning strategies.</span></div>
	</section>
</template>

<script setup>
import Button from "primevue/button"
import Tag from "primevue/tag"

const props = defineProps({ successful: { type: Array, default: () => [] }, failed: { type: Array, default: () => [] }, selected: { type: String, default: "" }, canSelect: Boolean, selecting: { type: String, default: "" }, compact: Boolean })
const emit = defineEmits(["select"])
function choose(strategy) { if (props.canSelect && !props.selecting && strategy !== props.selected) emit("select", strategy) }
function label(value) { return String(value || "").replaceAll("_", " ").replace(/\b\w/g, (char) => char.toUpperCase()) }
function number(value) { return Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 2 }) }
function outcome(result) { if (result.deduplicated) return `Same plan as ${label(result.same_as)}`; if (result.dominated) return `Dominated by ${label(result.dominated_by)}`; return result.error || result.status || "No feasible plan" }
</script>

<style scoped>
.planner-strategies { display: grid; padding: var(--erp-space-4); gap: var(--erp-space-4); }.planner-strategies__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 11px; }.planner-strategy-card { display: grid; min-width: 0; padding: 13px; gap: 12px; background: var(--erp-surface); border: 1px solid var(--erp-border); border-radius: var(--erp-panel-radius); cursor: pointer; transition: border-color .15s ease, box-shadow .15s ease, transform .15s ease; }.planner-strategy-card:hover { transform: translateY(-1px); border-color: var(--erp-border-strong); box-shadow: var(--erp-shadow-xs); }.planner-strategy-card--selected { background: var(--erp-accent-soft); border-color: var(--erp-accent); }.planner-strategy-card > header { display: flex; min-width: 0; align-items: center; gap: 9px; }.strategy-mark { display: grid; width: 34px; height: 34px; flex: 0 0 auto; place-items: center; color: var(--erp-accent); background: var(--erp-accent-soft); border-radius: 9px; }.planner-strategy-card > header > div:nth-child(2) { display: grid; min-width: 0; flex: 1; gap: 2px; }.planner-strategy-card h3 { margin: 0; color: var(--erp-text); font-size: var(--erp-font-size-caption); }.planner-strategy-card span { color: var(--erp-text-muted); font-size: var(--erp-font-size-min); }.strategy-metrics { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 1px solid var(--erp-border); border-radius: var(--erp-control-radius); overflow: hidden; }.strategy-metrics div { display: grid; padding: 7px; gap: 2px; text-align: center; border-right: 1px solid var(--erp-border); }.strategy-metrics div:last-child { border-right: 0; }.strategy-metrics span { text-transform: uppercase; }.strategy-metrics strong { color: var(--erp-text); font-size: var(--erp-font-size-caption); font-variant-numeric: tabular-nums; }
.planner-outcomes { border: 1px solid var(--erp-border); border-radius: var(--erp-panel-radius); overflow: hidden; }.planner-outcomes > header { display: flex; padding: 9px 12px; align-items: center; justify-content: space-between; color: var(--erp-text-muted); font-size: var(--erp-font-size-min); font-weight: 720; text-transform: uppercase; background: var(--erp-surface-muted); border-bottom: 1px solid var(--erp-border); }.planner-outcomes__list { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 8px; padding: 10px; }.planner-strategy-card--failed { display: flex; padding: 9px; align-items: center; gap: 8px; opacity: .82; cursor: default; }.planner-strategy-card--failed:hover { transform: none; box-shadow: none; }.planner-strategy-card--failed .strategy-mark { width: 28px; height: 28px; color: var(--erp-text-muted); background: var(--erp-surface-muted); }.strategy-empty { display: grid; min-height: 300px; place-content: center; justify-items: center; gap: 7px; color: var(--erp-text-muted); text-align: center; }.strategy-empty i { color: var(--erp-accent); font-size: 1.7rem; }.strategy-empty strong { color: var(--erp-text); }
.planner-strategies--compact { gap: 10px; }.planner-strategies--compact .planner-strategies__grid, .planner-strategies--compact .planner-outcomes__list { grid-template-columns: 1fr; gap: 7px; }.planner-strategies--compact .planner-strategy-card { position: relative; padding: 10px 30px 10px 10px; gap: 8px; }.planner-strategies--compact .strategy-mark { width: 30px; height: 30px; border-radius: 8px; }.planner-strategies--compact .strategy-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }.planner-strategies--compact .strategy-metrics div { padding: 5px 4px; }.planner-strategies--compact .strategy-metrics div:nth-child(2) { border-right: 0; }.planner-strategies--compact .strategy-metrics div:nth-child(-n + 2) { border-bottom: 1px solid var(--erp-border); }.planner-strategies--compact .strategy-state { position: absolute; top: 50%; right: 10px; color: var(--erp-text-muted); font-size: 11px; transform: translateY(-50%); }.planner-strategies--compact .strategy-state--selected { color: var(--erp-accent); font-size: 14px; }.planner-strategies--compact .planner-outcomes { border-radius: var(--erp-control-radius); }.planner-strategies--compact .planner-outcomes > header { padding: 7px 9px; }.planner-strategies--compact .planner-outcomes__list { padding: 7px; }.planner-strategies--compact .planner-strategy-card--failed { padding-right: 9px; }
</style>
